using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Text.RegularExpressions;
namespace Tvxd.Meps {
 public sealed class WireChoice061 {public string id=Guid.NewGuid().ToString("N"),name,group,color="#00FF00",pattern="LIỀN",presetLayer;public int weight=18;public double scale=1;public WireStyle010 sample;}
 public sealed class WireCatalog061 {
  public int version=1;public List<string> groups=new List<string>();public List<WireChoice061> wires=new List<WireChoice061>();public List<string> seenSamples=new List<string>();
  public static readonly string[] Patterns={"LIỀN","NÉT ĐỨT","CHẤM","GẠCH CHẤM","GIỮ MẪU"};
  public static readonly int[] Weights={0,5,9,13,15,18,20,25,30,35,40,50,53,60,70,80,90,100,106,120,140,158,200,211};
  public void Validate(){if(version!=1||groups==null||wires==null||seenSamples==null||groups.Count>100||wires.Count>1000)throw new InvalidDataException("DANH MỤC DÂY KHÔNG HỢP LỆ.");if(groups.Any(x=>string.IsNullOrWhiteSpace(x)||x.Length>60||x.Any(char.IsControl))||groups.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=groups.Count)throw new InvalidDataException("TÊN NHÓM RỖNG HOẶC TRÙNG.");var ids=new HashSet<string>();var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var w in wires){Guid id;if(w==null||!Guid.TryParseExact(w.id,"N",out id)||!ids.Add(w.id)||!groups.Contains(w.group)||string.IsNullOrWhiteSpace(w.name)||w.name.Length>160||w.name.Any(char.IsControl)||!names.Add(w.group+"\n"+w.name.Trim()))throw new InvalidDataException("KIỂM TRA TÊN DÂY, NHÓM HOẶC DÒNG TRÙNG.");if(!Regex.IsMatch(w.color??"",@"^#[0-9a-fA-F]{6}$")||!Patterns.Contains(w.pattern)||!Weights.Contains(w.weight)||!WireModel010.Finite(w.scale)||w.scale<=0||w.scale>10000)throw new InvalidDataException("KIỂM TRA MÀU #RRGGBB, KIỂU NÉT, ĐỘ DÀY VÀ TỶ LỆ.");if(w.pattern=="GIỮ MẪU"&&w.sample==null)throw new InvalidDataException("GIỮ MẪU CHỈ DÙNG CHO NÉT ĐÃ LẤY MẪU.");if(w.sample!=null)WireModel010.Validate(w.sample);}}
  public string Encode(){Validate();return new JavaScriptSerializer().Serialize(this);}
  public static WireCatalog061 Decode(string raw){if(raw==null||raw.Length>4000000)throw new InvalidDataException("DANH MỤC DÂY QUÁ LỚN.");var s=new JavaScriptSerializer{MaxJsonLength=4000000};var d=s.Deserialize<WireCatalog061>(raw);if(d==null)throw new InvalidDataException("DANH MỤC RỖNG.");d.Validate();return d;}
  public WireCatalog061 Clone(){return Decode(Encode());}
  public static void Save(string path,WireCatalog061 data,string expected){var raw=data.Encode();Directory.CreateDirectory(Path.GetDirectoryName(path));using(var gate=new FileStream(path+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){if(PipeRules057.Read(path)!=expected)throw new IOException("DANH MỤC ĐÃ ĐỔI Ở CỬA SỔ KHÁC. ĐÓNG VÀ MỞ LẠI QUẢN LÝ DÂY.");string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,raw,new System.Text.UTF8Encoding(false));Decode(File.ReadAllText(temp));if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}}
  public WireStyle010 Style(WireChoice061 w,int units,double globalScale,WireSettings010 settings){Validate();var s=w.sample==null?new WireStyle010{id=w.id,layer=w.presetLayer??"TVXD_WIRE_"+w.id,units=units,globalScale=globalScale,msltscale=settings.msltscale,annoScale=settings.annoScale,annoName=settings.annoName}:new JavaScriptSerializer().Deserialize<WireStyle010>(new JavaScriptSerializer().Serialize(w.sample));s.id=w.id;s.name=w.name;s.catalogPresetLayer=w.presetLayer;s.rgb=true;s.red=Convert.ToInt32(w.color.Substring(1,2),16);s.green=Convert.ToInt32(w.color.Substring(3,2),16);s.blue=Convert.ToInt32(w.color.Substring(5,2),16);s.layerRgb=true;s.layerRed=s.red;s.layerGreen=s.green;s.layerBlue=s.blue;s.lineweight=w.weight;s.layerWeight=w.weight;s.scale=w.scale;if(w.pattern!="GIỮ MẪU"){s.dashes=w.pattern=="LIỀN"?new double[0]:w.pattern=="NÉT ĐỨT"?new[]{6.0,-3.0}:w.pattern=="CHẤM"?new[]{0.0,-2.0}:new[]{6.0,-2.0,0.0,-2.0};s.patternLength=s.dashes.Sum(x=>Math.Abs(x));s.linetype=w.pattern=="LIỀN"?"Continuous":"TVXD_WIRE_"+w.id+"_"+w.pattern.Replace(' ','_');}WireModel010.Validate(s);return s;}
 }
}
